arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"query { q: __type(name: \"Query\") { fields { name args { name type { name kind ofType { name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['q']['fields']:
    if f['name'] in ('issue','issues'):
        print(f['name'])
        for a in f['args']:
            print('  ', a['name'], json.dumps(a['type']))
"

